function biggestRise(nums: number[]): number {
  let best = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (nums[j] > nums[i]) best = Math.max(best, nums[j] - nums[i]);
  return best;
}

