function biggestRise(nums: number[]): number {
  let low = nums[0], best = -1;
  for (let j = 1; j < nums.length; j++) {
    if (nums[j] > low) best = Math.max(best, nums[j] - low);
    low = Math.min(low, nums[j]);
  }
  return best;
}

